const fs = require('node:fs');
const assert = require('node:assert/strict');
const crypto = require('node:crypto');
const read = (file) => fs.readFileSync(file);
const json = (file) => JSON.parse(read(file));
const hash = (file) => crypto.createHash('sha256').update(read(file)).digest('hex');
const generationPath = 'docs/evidence/attempts/Phase008/setup/migration-generation.json';
const receiptPath = 'docs/phase-plans/Phase008-inputs.json';
const sourceSchemaPath = 'prisma/schema.prisma';
const original = json(generationPath);
const migrationPath = original.generatedMigrationPath;
const source = read('docs/phase-plans/verify-phase008.mjs').toString();
const extracted = source.slice(source.indexOf('function verifyMigrationBinding()'), source.indexOf('function scanScope()'));
assert(extracted.startsWith('function verifyMigrationBinding()'));
const make = new Function('assert', 'json', 'generationPath', 'migrationPath', 'receiptPath', 'hash', 'read', 'sourceSchemaPath', extracted + '\nreturn verifyMigrationBinding;');
make(assert, json, generationPath, migrationPath, receiptPath, hash, read, sourceSchemaPath)();
const results = [];
for (const [name, record] of [
 ['echoed-create-only-is-accepted', {command:'echo --create-only',exitCode:0,timedOut:false}],
 ['missing-timeout-and-streams-is-accepted', {command:'npm run db:migrate -- --name travel_record_chat_message --create-only',exitCode:0}]
]) {
 const generation = structuredClone(original);
 generation.records = [record];
 make(assert, (file) => file === generationPath ? generation : json(file), generationPath, migrationPath, receiptPath, hash, read, sourceSchemaPath)();
 results.push({name, suppliedRecord:record, actual:'ACCEPT', required:'REJECT'});
}
console.log(JSON.stringify({probe:'generated-migration-command-validation', actualReceiptAccepted:true, filesModified:false, databaseAccessed:false, results}));

const fs = require('node:fs');
const assert = require('node:assert/strict');
const source = fs.readFileSync('docs/phase-plans/prepare-phase008.mjs', 'utf8');
const extracted = source.slice(source.indexOf('assert.equal(preflight.shells.length, 2);'), source.indexOf('assert.equal(git("config"'));
assert(extracted.startsWith('assert.equal(preflight.shells.length, 2);'));
const check = new Function('assert', 'preflight', extracted);
const preflight = JSON.parse(fs.readFileSync('docs/evidence/attempts/Phase008/setup/preflight.json', 'utf8'));
check(assert, preflight);
const actualShells = preflight.shells.map((entry) => entry.shell);
preflight.shells[1] = structuredClone(preflight.shells[0]);
check(assert, preflight);
console.log(JSON.stringify({probe:'dual-shell-admission-identity', actualReceiptAccepted:true, actualShells, suppliedShells:preflight.shells.map((entry) => entry.shell), actual:'ACCEPT', required:'REJECT', filesModified:false, databaseAccessed:false}));
